async function run(input, tools) {
  const res = await tools.web.fetch({ url: "https://api.coingecko.com/api/v3/simple/price?ids=ethereum&vs_currencies=usd" });
  let price;
  try {
    const body = JSON.parse(res.text);
    price = Number(body && body.ethereum && body.ethereum.usd);
  } catch (e) {
    price = NaN;
  }

  const mem = input && input.memory ? input.memory : {};
  const above = String(mem.price_above_target).toLowerCase() === "true";
  const alerted = String(mem.last_alert_sent).toLowerCase() === "true";

  const belowTarget = Number.isFinite(price) && price < Number(mem.target_price ?? NaN) === false
    ? Number.isFinite(price) && typeof mem.target_price !== "undefined" && price < Number(mem.target_price)
    : Number.isFinite(price) && price < Number(mem.target_price);

  let way;
  if (!belowTarget) {
    way = "price_above_target";
  } else if (alerted) {
    way = "price_below_and_alerted";
  } else {
    way = "price_below_and_not_alerted";
  }

