async function run(input, tools) {
  const settings = input.settings || {};
  const sheet = settings.sales_sheet;
  let last = Number(input.last_position);
  if (!Number.isFinite(last) || last < 0) last = 0;

  if (!sheet) return { today_rows: [] };

  const res = await tools.sheets.read({ sheet: String(sheet) });
  const rows = (res && Array.isArray(res.rows)) ? res.rows : [];

  const now = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  const today = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;

  const norm = (v) => {
    if (v === null || v === undefined) return "";
    return String(v).trim();
  };

  const isToday = (cell) => {
    const s = norm(cell);
    if (!s) return false;
    if (s === today) return true;
    if (s.startsWith(today)) return true;
    const parsed = new Date(s);
    if (!isNaN(parsed.getTime())) {
      return parsed.getFullYear() === now.getFullYear() &&
        parsed.getMonth() === now.getMonth() &&
        parsed.getDate() === now.getDate();
    }
    return false;
  };

  const today_rows = [];
  for (const row of rows) {
    if (!row || typeof row !== "object") continue;
    const rowIndex = Number(row._row);
    if (!Number.isFinite(rowIndex)) continue;
    if (rowIndex < last) continue;

    const keys = Object.keys(row).filter((k) => k !== "_row");
    let dateKey = keys.find((k) => /date/i.test(k));
    if (!dateKey) dateKey = keys.find((k) => isToday(row[k]));
    if (!dateKey) continue;
    if (!isToday(row[dateKey])) continue;

    let amountKey = keys.find((k) => /amount/i.test(k));
    const amount = amountKey ? row[amountKey] : null;

    today_rows.push({ _row: rowIndex, amount: amount });
  }

  return { today_rows };
}
