    rows = result.rows || [];
  } catch (error) {
    return {
      pending_restock_items: [],
      check_work_exists_way: "no_items_below_minimum"
    };
  }

  const items = [];
  let totalRestockCost = 0;

  for (const row of rows) {
    const itemName = row.item_name || row["Item Name"] || "";
    const currentQty = Number(row.current_quantity || row["Current Quantity"] || 0);
    const minimumQty = Number(row.minimum_quantity || row["Minimum Quantity"] || 0);
    const pricePerUnit = Number(row.price_per_unit || row["Price Per Unit"] || 0);

    const restockQty = Math.max(0, minimumQty - currentQty);

    if (restockQty > 0) {
      const restockCost = restockQty * pricePerUnit;
      totalRestockCost += restockCost;

      items.push({
        item_name: itemName,
        current_quantity: currentQty,
        minimum_quantity: minimumQty,
        price_per_unit: pricePerUnit,
        restock_quantity: restockQty,
        restock_cost: restockCost
      });
    }
  }

  items.total_restock_cost = totalRestockCost;

  const checkWorkExistsWay = items.length > 0 
    ? "items_below_minimum" 
    : "no_items_below_minimum";

  return {
    pending_restock_items: items,
    check_work_exists_way: checkWorkExistsWay
  };
}
